/**
 * Render an invoice as plain text for display to a customer.
 * @param {{ number?: string, customerId: string, issueDate?: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, status?: string, voucher?: { code: string, amount: number }, payments?: Array }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : invoice.customerId;

  // Get invoice header
  const invoiceNumber = invoice.number ?? 'DRAFT';

  // Get totals
  const totals = invoiceTotals(invoice);

  // Build lines
  const lines = [];
  lines.push(invoiceNumber);
  lines.push(customerName);
  lines.push('');

  // Add each line item
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyStr = line.qty === 1 ? '1x' : `${line.qty}x`;
    const unitPriceStr = formatEuros(line.unitPrice);
    const lineTotalStr = formatEuros(total);
    lines.push(`${qtyStr} ${line.name} @ ${unitPriceStr} = ${lineTotalStr}`);

    // Show line discount if any
    const discount = lineDiscount(line);
    if (discount > 0) {
      lines.push(`  Discount: -${formatEuros(discount)}`);
    }
  }

  lines.push('');
  if (totals.subtotal !== totals.total || totals.vat > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  }
  if (totals.discount > 0) {
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }
  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Add due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if there are payments
  const totalPaid = totals.total - balanceDue(invoice);
  if (totalPaid > 0) {
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

